__NUXT_JSONP__("/think-tanks/eventos/se_requieren_soluciones_innovadoras_para_el_trabajo_digno_y_sostenible", (function(a,b,c,d){return {data:[{post:{slug:"se_requieren_soluciones_innovadoras_para_el_trabajo_digno_y_sostenible",title:"Se requieren soluciones innovadoras para el trabajo digno y sostenible",date:"2025-02-27T16:25:59.751Z",img:"https:\u002F\u002Fucarecdn.com\u002Fd541194b-ef29-40a8-b59d-966dff917bc3\u002F-\u002Fcrop\u002F4025x2833\u002F0,92\u002F-\u002Fpreview\u002F","img-alt":"Javier González, Ethos",autor:"Ethos",category:"think-tanks",extracto:"Javier González, director de Desarrollo Institucional en Ethos, moderó una sesión grabada en el Innovation Island Summit 2025 en Colombo, Sri Lanka, en la que se abordó el tema de empleos dignos para un futuro sostenible.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"La creciente crisis mundial del desempleo requiere una acción urgente, pues el panorama muestra que en la próxima década entrarán a la fuerza laboral 1,200 millones de personas de economías emergentes y la expectativa de la creación de empleos es de solo 420 millones durante ese lapso."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Ante esta realidad, dentro del Innovation Island Summit 2025, se realizó una sesión para abordar el tema, denominada \"Empleos Dignos para Todos: Trabajo para un Futuro Sostenible\". El moderador fue Javier González, director de Desarrollo Institucional en Ethos, y participaron como ponentes, Khalila Mbowe, fundadora y directora general de la organización Unleashed Africa Company Limited de Tanzania, y Sharanya Sekaram, especialista en género de Sri Lanka."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Entre los temas que se abordaron destacan el potencial de la economía verde y digital para crear empleos dignos y sostenibles, la necesidad de colaboración entre empresas y gobierno para promover el trabajo digno e inclusivo, así como de contar con innovaciones y colaboraciones para abordar el impacto del desempleo en las mujeres y reducir las disparidades de género."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El Innovation Island Summit 2025 se realizó en Colombo, Sri Lanka, y reunió a múltiples actores para debatir estrategias de desarrollo sostenible e innovación en economías emergentes. El evento se enfocó en seis pilares clave: la planificación de la Agenda Post-2030 para un crecimiento equilibrado; la adopción de tecnologías emergentes como la IA para mejorar la gobernanza; la resiliencia climática y la transición hacia energías sostenibles; el papel de mujeres y jóvenes en la transformación social y económica; el fortalecimiento de la economía azul mediante la pesca sostenible y el ecoturismo marino; y las lecciones de la recuperación económica de Sri Lanka tras su crisis de 2022."}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fse_requieren_soluciones_innovadoras_para_el_trabajo_digno_y_sostenible",extension:".md",createdAt:"2025-04-23T06:21:15.374Z",updatedAt:"2025-04-23T06:21:15.375Z"}}],fetch:{},mutations:[]}}("text","element","p","\n")));